const blocs = $('Blocs récurrents').first().json;
const excludedUrls = $('Lire historique').all().map(item => (item.json.url || '').trim()).filter(Boolean);

const now = new Date();
const moisAnnee = now.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });

const systemPrompt = "Tu es le redacteur de la newsletter mensuelle d’un professionnel de l’immobilier francais (agent, plus un reseau d’apporteurs d’affaires et de consultants). Utilise l’outil de recherche web pour trouver, pour CHACUN des 4 themes suivants, 1 a 2 articles recents (de preference des dernieres semaines), fiables et en francais : (1) economie et taux d’interet / marche immobilier, (2) reglementation immobiliere (lois, fiscalite, diagnostics...), (3) amenagement et travaux, (4) confort thermique et energie dans le logement. Privilegie des sources serieuses (presse specialisee, sites institutionnels, notaires, ADEME, etc.). Ne propose jamais une URL presente dans cette liste deja utilisee : " + JSON.stringify(excludedUrls) + ". Une fois tes recherches terminees, termine ta reponse par UNIQUEMENT un objet JSON valide (rien avant, rien apres), au format exact : {\"sections\":[{\"category\":\"...\",\"categoryLabel\":\"...\",\"titre\":\"...\",\"synthese\":\"...\",\"source_url\":\"...\"}],\"intro_apporteur\":\"...\",\"intro_recrutement\":\"...\"}. Chaque synthese fait 3 a 5 phrases, ton professionnel et chaleureux, sans jargon, destinee a des particuliers proprietaires ou vendeurs. intro_apporteur et intro_recrutement sont une phrase d’accroche originale et renouvelee introduisant les blocs fixes fournis ci-dessous, sans en changer le fond.";

const userPrompt = "Mois de la newsletter : " + moisAnnee + ".\nBloc apporteur d’affaires existant : " + blocs.texte_apporteur + "\nBloc recrutement existant : " + blocs.texte_recrutement;

return [{
  json: {
    moisAnnee,
    claudeRequestBody: {
      model: 'claude-opus-5',
      max_tokens: 8000,
      system: systemPrompt,
      tools: [
        {
          type: 'web_search_20260209',
          name: 'web_search',
          max_uses: 16,
        },
      ],
      messages: [
        { role: 'user', content: userPrompt },
      ],
    },
  },
}];

const blocks = $json.content || [];
const textBlocks = blocks.filter(b => b.type === 'text');
const raw = textBlocks.length ? textBlocks[textBlocks.length - 1].text : '';
const cleaned = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  // Claude a parfois ajoute du texte avant/apres le JSON (ex: limite d'outils atteinte).
  // On extrait le premier bloc { ... } valide dans la reponse.
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace === -1 || lastBrace === -1 || lastBrace < firstBrace) {
    throw new Error('Reponse Claude non parseable en JSON : ' + raw);
  }
  try {
    data = JSON.parse(cleaned.slice(firstBrace, lastBrace + 1));
  } catch (e2) {
    throw new Error('Reponse Claude non parseable en JSON : ' + raw);
  }
}

return [{ json: data }];

const data = $json;
const blocs = $('Blocs récurrents').first().json;
const moisAnnee = $('Préparer le prompt').first().json.moisAnnee;

const lignes = [];
lignes.push('NEWSLETTER IMMOBILIÈRE - ' + moisAnnee.toUpperCase());
lignes.push('');

for (const section of data.sections || []) {
  lignes.push('— ' + (section.categoryLabel || section.category).toUpperCase() + ' —');
  lignes.push(section.titre || '');
  lignes.push(section.synthese || '');
  if (section.source_url) lignes.push('Source : ' + section.source_url);
  lignes.push('');
}

lignes.push('— DEVENIR APPORTEUR D’AFFAIRES —');
lignes.push(data.intro_apporteur || '');
lignes.push(blocs.texte_apporteur || '');
lignes.push('');

lignes.push('— REJOINDRE L’ÉQUIPE —');
lignes.push(data.intro_recrutement || '');
lignes.push(blocs.texte_recrutement || '');

return [{
  json: {
    titreDoc: 'Newsletter immobilière - ' + moisAnnee,
    texteFinal: lignes.join('\n'),
    urlsSelectionnees: (data.sections || []).map(s => s.source_url).filter(Boolean),
  },
}];

const data = $json;
const today = new Date().toISOString().slice(0, 10);
return (data.urlsSelectionnees || []).map(url => ({ json: { url, date: today } }));
